# region: sift
def sift(raw):
    out = []
    for tok in raw:
        s = tok.strip()
        if s.isdigit() and int(s) > 0:
            out.append(int(s))
    return out

# region: shape
def shape(xs, offset=1):
    return [v - offset for v in xs]

# region: render
def render(xs, floor_=2):
    return [v for v in xs if v >= floor_]

# region: intake
def intake(xs):
    return {'n': len(xs), 'min': min(xs) if xs else 0, 'span': (max(xs) - min(xs)) if xs else 0}

# region: digest
def digest(summary, bar=2):
    out = dict(summary)
    n = summary.get('n', 0)
    out['ratio'] = round(n / bar, 3) if bar else 0.0
    return out

# region: run
def run(raw):
    return digest(intake(render(shape(sift(raw)))))

